const oppRes = await tool.fetch_url({ url: "https://terac.com/opportunities" });
const oppMatches = [...oppRes.body.matchAll(/href="(\/opportunities\/[^"]+)"/g)].map(m => m[1]);
const uniqueOpps = [...new Set(oppMatches)];

let foundSM = [];
for (let i = 0; i < uniqueOpps.length; i += 10) {
  const batch = uniqueOpps.slice(i, i + 10);
  const promises = batch.map(async (path) => {
    try {
      const res = await tool.fetch_url({ url: "https://terac.com" + path });
      if (res.body && res.body.toLowerCase().includes("surveymonkey")) {
        return { path, body: res.body };
      }
    } catch (e) {}
    return null;
  });
  const results = await Promise.all(promises);
  for (const r of results) {
    if (r) foundSM.push(r);
  }
}
console.log("Found SurveyMonkey in opportunities:", foundSM.length);
